"""Authored, sequential slide content mapped to the four existing Quarto lessons."""
import json, re, hashlib
from pathlib import Path

ROOT = Path.cwd()
BASE = ROOT / '20261/modules/01-introduction-to-r'
OUT = ROOT / '20261/_output/.module01-teaching-build'
OUT.mkdir(parents=True, exist_ok=True)
FILES = {i: sorted(BASE.glob(f'{i:02d}-*.qmd'))[0] for i in range(1,5)}
SOURCES = {i:p.read_text() for i,p in FILES.items()}
SLIDES=[]

def section(lesson, query):
    lines=SOURCES[lesson].splitlines()
    found=[]; inside=False
    for i,line in enumerate(lines):
        if line.lstrip().startswith('```'): inside=not inside
        m=re.match(r'^(#{1,6}) (.+)',line)
        if not inside and m: found.append((i,len(m[1]),m[2]))
    if query=='__intro__':
        return 1, found[0][0] if found else len(lines), '\n'.join(lines[:found[0][0]])
    matches=[h for h in found if h[2]==query]
    if not matches: raise ValueError((lesson,query))
    start,level,_=matches[0]
    end=next((h[0] for h in found if h[0]>start and h[1]<=level),len(lines))
    return start+1,end,'\n'.join(lines[start:end])

def add(lesson, heading, title, body='', code='', comments=(), image=None, arabic='', hint='', kind='content', refs=(), plot=None):
    start,end,original=section(lesson,heading)
    if code:
        if len(comments)<2: raise ValueError(('Two code comments required',title))
        code='\n'.join('# '+x for x in comments)+'\n'+code.strip()
    SLIDES.append(dict(lesson=lesson,title=title,body=body,code=code,image=image,arabic=arabic,hint=hint,kind=kind,refs=list(refs),plot=plot,source=FILES[lesson].name,heading=heading,start=start,end=end,original=original))

def divider(lesson,title,body,heading='__intro__'):
    add(lesson,heading,title,body,kind='divider')

divider(1,'Module 1: Introduction to R','R and RStudio\nBasic concepts in R\nData manipulation with dplyr\nVisualization with ggplot2')
divider(1,'Lesson 1: R and RStudio','Set up the tools, then explore the workspace.')
add(1,'__intro__','R and RStudio','R is the language and computing environment.\nRStudio is an interface for writing and running R.\nUse them together for analysis and graphics.')
add(1,'History of R','History of R','Ross Ihaka and Robert Gentleman developed R in Auckland.\nR draws on S and lexical scoping from Scheme.\nThe name refers to its creators and to S.\n1993: public announcement. 1995: source released under the GPL.',refs=['https://cran.r-project.org/doc/html/interface98-paper/paper_2.html'])
add(1,'Main Features of R','Analysis, graphics, and packages','Statistical methods: models, tests, time series, and more.\nGraphics help explore and communicate data.\nPackages extend R with functions and datasets.\nCRAN distributes contributed packages.')
add(1,'Main Features of R','Programming, data, and support','Objects hold vectors, matrices, arrays, lists, and tables.\nConditions, loops, and functions organize calculations.\nInput and output connect R to files and other systems.\nDocumentation, forums, and contributors support users.')
add(1,'Advantages of R','Advantages of R','Free, open source, and available on Windows, macOS, and Linux.\nAn active community maintains tools and documentation.\nR can connect with languages such as C, C++, and Python.')
add(1,'Data Science and R','R in a data analysis workflow','Prepare data with tools such as dplyr and tidyr.\nApply statistical methods to answer a question.\nUse ggplot2 to communicate patterns and results.',hint='The next lessons follow this workflow.')
add(1,'Career Opportunities with R','Careers using R: analysis and business','Data analyst: prepare and interpret data.\nData scientist: develop models and predictions.\nQuantitative analyst: study financial data and risk.\nStatistician: design studies and analyze evidence.\nMarket research analyst: study customers and markets.')
add(1,'Career Opportunities with R','Careers using R: research and modeling','Bioinformatician / biostatistician: analyze biological data.\nMachine learning engineer: develop learning algorithms.\nEconometrician: model economic relationships.\nEnvironmental scientist: analyze environmental data.\nPublic health analyst: assess population health evidence.')
add(1,'Career Opportunities with R','Careers using R: applied decisions','Educational researcher: evaluate learning and programs.\nActuary: quantify insurance and financial risk.\nOperations research analyst: improve decisions and processes.\nSports analyst: examine performance and strategy.\nClinical researcher: analyze studies and trials.')
add(1,'Installing R: A Step-by-Step Guide','Installation order','1. Download and install R from CRAN.\n2. Install RStudio Desktop from Posit.\n3. Open RStudio and check that R starts.',hint='Choose installers compatible with your operating system.',refs=['https://docs.posit.co/ide/user/download.html'])
add(1,'For Windows Users','Installing R on Windows','Open CRAN and choose the Windows base installer.\nRun the .exe and follow the setup prompts.\nChoose the installation folder and components.\nFinish setup, then install RStudio Desktop.')
add(1,'For macOS Users','Installing R on macOS','Choose the R .pkg matching your Mac and macOS.\nRun the installer and follow its prompts.\nUse the current CRAN instructions for compatibility.\nThen install RStudio Desktop.',hint='The Quarto screenshots and menu wording may reflect an older release.')
add(1,'For Linux Users','Installing R on Linux','Installation depends on the Linux distribution.\nFor Debian / Ubuntu, use the package manager.\nAn optional CRAN repository must match your distribution.',hint='Terminal commands: sudo apt update, then sudo apt install r-base')
add(1,'Additional Steps for All Users','Installation check','Open R or the RStudio Console.\nInspect the R version, platform, and attached packages.',code='sessionInfo()',comments=['sessionInfo() reports the current R session.','Use its version and platform details when diagnosing setup issues.'])
add(1,'Presenting the R Console','Opening the R Console','On Windows, find R in the Start menu.\nOpen the application to reach the command prompt.',image='20261/assets/module01/r-folder.png')
add(1,'Presenting the R Console','The R Console','Type commands after the > prompt.\nR evaluates them and prints results.',image='20261/assets/module01/r-console.png')
add(1,'Presenting the R Studio','The RStudio workspace','Find the Source editor, Console, and Environment.\nUse Files, Plots, Packages, and Help while working.',image='20261/assets/module01/rstudio.png')
add(1,'Settings - Working Directory','Working directory settings','The working directory is the starting point for relative paths.\nIn RStudio, find the General options.',image='20261/assets/module01/rstudio-settings-01.png')
add(1,'Settings - Working Directory','Default working directory','The lesson illustrates choosing a default folder.\nFor this course, open the supplied RStudio project.',image='20261/assets/module01/rstudio-settings-02.png',hint='Course CSV paths resolve from the 20261 project folder.')
add(1,'Settings - Working Directory','Changing the working directory','The Session menu also provides directory controls.\nCheck the active folder when a file cannot be found.',image='20261/assets/module01/rstudio-settings-03.png')
add(1,'References','Lesson 1 references','Penn State STAT 484\nPenn State Essential R notes\nCyclismo R tutorial\nR for Data Analysis in easy steps / R Programming Essentials',hint='Links and the original attribution are in the Quarto lesson.')
divider(2,'Lesson 2: Basic concepts in R','With the workspace ready, start writing and reading R code.')
add(2,'Hello World Program','Hello, World','Run the same short program in the Console and in a script.\nAn assignment stores a value. print() displays it.',code='myString <- "Hello, World!"\nprint(myString)',comments=['<- stores the text in the object myString.','print() displays that stored object in the Console.'])
add(2,'R Command Prompt','The command prompt and printed output','In a system terminal, R starts an interactive R session.\nInside R, the > prompt waits for a command.\nThe printed [1] marks the first value shown on that output line.',hint='System-terminal commands and R expressions use different prompts.')
add(2,'Writing R Script File','Reusable R scripts','Save the Hello World commands in test.R.\nRun the script in RStudio or use Rscript test.R in a terminal.\nA script keeps a repeatable record of the commands.')
add(2,'Comments','Comments explain the code','Text following # is a comment.\nR ignores comments when it evaluates the program.',code='# My first program in R Programming',comments=['Comments describe intent and important assumptions.','Keep executable expressions on their own lines when possible.'])
add(2,'Variables and Basic Data Types','Variables and objects','A name refers to an R object.\nAssignment creates or replaces the value under that name.\nR determines the type from the assigned object.\nTypes describe values; structures organize those values.',hint='Next: numeric, complex, character, and logical values.')
add(2,'Numeric Variables','Numeric and integer values','Numeric values commonly use double precision.\nThe L suffix explicitly creates an integer.',code='count <- 42L\nweight <- 72.5',comments=['42L is stored as an integer; 72.5 is stored as a double.','<- assigns each value to the name on its left.'])
add(2,'Numeric Variables','Complex values','A complex value has real and imaginary components.',code='complex_num <- 3 + 4i',comments=['The suffix i represents the imaginary component.','This value has real part 3 and imaginary part 4.'])
add(2,'Numeric Variables','Character values','Character values store text in quotation marks.\nA single character string can contain many letters.',code='name <- "Alice"\nsentence <- "Hello, World!"',comments=['Quotation marks distinguish text from an object name.','Both assignments create character values.'])
add(2,'Numeric Variables','Logical values: Boolean results','TRUE and FALSE represent logical values.\nComparisons produce logical results.\nUse full names rather than the reassignable T and F aliases.',code='is_valid <- TRUE\ntest_result <- 5 > 3\na <- TRUE\nb <- FALSE\na | b\na & b',comments=['> tests whether the left value exceeds the right value.','| means OR; & requires both elementwise conditions to be TRUE.'])
add(2,'R is Case Sensitive','Case sensitivity','age, Age, and AGE are different names.\nFunction names also require the correct capitalization.',code='age <- 25\nprint(age)\n# Intentional error examples:\nprint(Age)\nPrint(age)',comments=['print() displays a value; capitalized Print() is a different name.','Only age is defined here, so the last two calls intentionally fail.'],hint='Run error demonstrations separately from a working analysis.')
add(2,'Get Data Type of a Variable','A table with different column types','The lesson constructs a small BMI example table.\nRows align the values belonging to each person.',code='BMI <- data.frame(\n  gender = c("Male", "Male", "Female"),\n  height = c(152, 171.5, 165),\n  weight = c(81, 93, 78),\n  Age = c(42, 38, 26)\n)',comments=['c() combines values; data.frame() aligns the columns into a table.','Columns can have different types but must have compatible lengths.'],hint='Illustrative records from the lesson; source does not state height/weight units.')
add(2,'Get Data Type of a Variable','Inspecting type and structure','class() reports the object class.\ntypeof() reports the underlying storage type.\nstr() shows the structure and example values.',code='class(BMI)\ntypeof(BMI)\nstr(BMI)',comments=['class() describes how an object behaves; typeof() describes storage.','str() displays columns, their types, and a compact preview.'])
add(2,'Logical operators in R:','Comparison operators','< and >: less than and greater than\n<= and >=: less than or equal and greater than or equal\n==: equal to\n!=: different from',hint='A comparison tests a relationship and returns a logical result.')
add(2,'Logical operators in R:','Combining logical conditions','& requires both conditions.\n| accepts either condition.\n! reverses TRUE and FALSE.',hint='These elementwise operators also work on logical vectors.')
add(2,'Complext Data Types and Data Structures','Organizing values','Vectors organize values along one dimension.\nMatrices and arrays organize values in more dimensions.\nLists can combine unlike objects.\nData frames organize observations and variables.\nFactors represent categories.',hint='Start with vectors, then move to the other structures.')
add(2,'Vectors','Vectors','An atomic vector holds values of one common type.\nCombining incompatible types can coerce them to a common type.',code='ages <- c(25, 30, 45)\ncolors <- c("red", "green", "blue")\nanswers <- c(TRUE, FALSE, TRUE)',comments=['c() combines values in their supplied order.','These examples create numeric, character, and logical vectors.'])
add(2,'Vectors','The lesson data table','Patient ID identifies the observation.\nHeight (cm), weight (kg), and blood pressure (mmHg) are columns.\nEach column can be represented as a vector.',hint='Illustrative table reproduced from the lesson; no clinical interpretation.',kind='patient-table')
add(2,'Creating Sequences in R','Creating sequences','Sequences are ordered values following a pattern.\nUse : for steps of one.\nUse seq() to control spacing or length.\nUse rep() to repeat values.',hint='The following examples distinguish spacing from repetition.')
add(2,'Using the Colon Operator `:`','Consecutive values with :','The colon operator steps by one toward the endpoint.',code='seq_1_to_10 <- 1:10\nprint(seq_1_to_10)',comments=['1:10 creates the integers from 1 through 10.','print() displays the sequence saved by the assignment.'])
add(2,'The `seq()` Function','Sequence spacing with seq()','from and to set the endpoints.\nby specifies the step size.',code='seq_by_2 <- seq(from = 1, to = 10, by = 2)\nprint(seq_by_2)',comments=['seq() generates values with the requested spacing.','by = 2 gives 1, 3, 5, 7, 9; the endpoint need not be reached.'])
add(2,'The `seq()` Function','Sequence length with seq()','length.out requests the number of evenly spaced values.',code='seq_length_out <- seq(from = 5, to = 10, length.out = 3)\nprint(seq_length_out)',comments=['length.out = 3 requests three values including the endpoints.','print() displays 5, 7.5, and 10.'])
add(2,'The `rep()` Function','Repeating a whole vector','times repeats the complete input vector.',code='rep_times <- rep(x = 1:3, times = 3)\nprint(rep_times)',comments=['rep() repeats supplied values; 1:3 creates 1, 2, 3.','times = 3 repeats that whole sequence three times.'])
add(2,'The `rep()` Function','Repeating individual elements','each repeats every element before moving to the next.',code='rep_each <- rep(x = 1:3, each = 3)\nprint(rep_each)',comments=['rep() repeats values; each = 3 repeats each input three times.','Compare 1,1,1,2,2,2,3,3,3 with the times example.'])
add(2,'Combining Sequences','Combining sequences','Use c() to join generated sequences.',code='combined_seq <- c(seq(1, 5), seq(8, 10))\nprint(combined_seq)',comments=['seq() creates steps of one here; c() joins the two sequences.','print() shows 1 to 5 followed by 8 to 10, preserving that order.'])
add(2,'Practice Vectors','Vector practice: combinations','Combine 1, 2, 3 with "a", "b", "c".\nTake every second number from 1 to 10.\nRepeat 1,2,3 twice, followed by 4,5,6 twice.\nStart with 1,2,3, then repeat 4 five times.',hint='Pause here and complete the matching Quarto prompts.')
add(2,'Practice Vectors','Vector practice: patterns','Create the first 10 even numbers.\nCreate the first 10 odd numbers.\nUse seq() to generate 1 to 10, repeating each value twice.\nUse rep() to repeat the sequence 1,2,3 three times.',hint='Keep these as student attempts; return to the lesson for practice.')
add(2,'Access Vector Elements','Vector indexing','Square brackets select values.\nR counts positions from 1.\nStart with the same vector throughout these examples.',code='numbers <- c(10, 20, 30, 40, 50)',comments=['c() creates five values in the displayed order.','Positions 1 through 5 refer to those five values.'])
add(2,'Single Element Access','One vector element','Select the third position.',code='third_number <- numbers[3]\nprint(third_number)',comments=['[3] extracts the value in position 3.','print() displays 30 from the vector defined on the previous slide.'])
add(2,'Multiple Elements Access','Several vector positions','Supply a vector of positions inside brackets.',code='selected_numbers <- numbers[c(1, 3, 5)]\nprint(selected_numbers)',comments=['c(1, 3, 5) identifies three selected positions.','The bracket expression returns 10, 30, and 50.'])
add(2,'Sequential Elements Access','A consecutive range','Use a sequence of indices to select a range.',code='range_numbers <- numbers[2:4]\nprint(range_numbers)',comments=['2:4 identifies positions 2, 3, and 4.','The bracket expression returns 20, 30, and 40.'])
add(2,'Conditional Access','Values matching a condition','A logical condition can select values directly.',code='filtered_numbers <- numbers[numbers > 25]\nprint(filtered_numbers)',comments=['numbers > 25 marks qualifying values as TRUE.','Logical indexing keeps 30, 40, and 50 in their original order.'])
add(2,'Find the Index of Matching Elements','Positions matching a condition','which() returns positions rather than the selected values.',code='which(numbers > 25)',comments=['which() returns the integer positions of TRUE conditions.','The result is 3, 4, 5; compare it with values 30, 40, 50.'])
add(2,'Excluding Elements','Excluding vector positions','Negative indices omit the specified positions.',code='exclude_second <- numbers[-2]\nexclude_range <- numbers[-(2:4)]\nprint(exclude_second)\nprint(exclude_range)',comments=['A negative index excludes positions rather than selecting them.','Parentheses make -(2:4) exclude positions 2 through 4 together.'])
add(2,'Named Vectors','Named vector elements','Names provide another way to select vector values.',code='fruits <- c(apple = 10, banana = 5, cherry = 8)\nbanana_count <- fruits["banana"]\nsome_fruits <- fruits[c("apple", "cherry")]\nprint(banana_count)\nprint(some_fruits)',comments=['c() creates a named vector; quoted names select its elements.','Single brackets preserve the selected names in the result.'])
add(2,'Basic Operations on Vectors','Arithmetic on every element','An arithmetic operation applies to each vector entry.\nReassigning a saves the updated values.',code='a <- c(1, 2, 3, 4)\na <- a + 5\na <- a - 10\na <- a / 5\nb <- a',comments=['c() creates the vector; each arithmetic step changes every value.','b <- a saves the current values under another name.'])
add(2,'Basic Operations on Vectors','Powers, roots, exponentials, and logarithms','Functions can also operate on an entire numeric vector.',code='a <- c(1, 2, 3, 4)\na ^ 2\nsqrt(a)\nexp(a)\nlog(a)\nexp(log(a))',comments=['^ raises powers; sqrt() takes roots; exp() computes e to a power.','log() uses natural logarithms by default; check input domains.'])
add(2,'Basic Operations on Vectors','Combining vector expressions','Parentheses determine the calculation order.\nVector pairs combine element by element.',code='c <- (a + sqrt(a)) / (exp(2) + 1)\na + b\na * b\na / b\n(a + 3) / (sqrt(1 - b) * 2 - 1)',comments=['sqrt() and exp() act on their inputs before the surrounding arithmetic.','Check zero denominators and square-root domains before interpreting results.'],hint='These continue the lesson objects; they illustrate syntax, not a data finding.')
add(2,'Basic Operations on Vectors','Unequal lengths and recycling','R recycles the shorter vector.\nA nonmultiple length produces a warning.\nEqual lengths are the clearest choice for paired observations.',code='a <- c(1, 2, 3)\nb <- c(10, 11, 12, 13)\na + b',comments=['c() creates unequal vector lengths of three and four.','This intentional warning example recycles a and warns about the length mismatch.'])
add(2,'Basic Numerical Descriptors','Numerical summaries','mean() and median(): center\nquantile(): percentiles\nvar() and sd(): spread\nmin() and max(): endpoints',code='a <- 1:10\nmean(a); median(a); quantile(a)\nvar(a); sd(a)\nmin(a); max(a)',comments=['quantile() uses type = 7 by default here; var() divides by n - 1.','sd() is the sample standard deviation, in the original measurement units.'],hint='Module 2 develops the interpretation of these measures.')
add(2,'Basic Numerical Descriptors','An overview with summary()','Numerical summaries include quartiles, center, and endpoints.\nFor a data frame, summary() works column by column.',code='summary(a)\nsummary(mtcars)',comments=['summary() chooses an overview suited to the object type.','For numeric columns it reports min, quartiles, median, mean, and max.'])
add(2,'Sorting Vectors','Sorting vector values','sort() returns values in increasing order by default.',code='a <- c(2, 4, 6, 3, 1, 5)\nb <- sort(a)\nc <- sort(a, decreasing = TRUE)',comments=['c() combines the unsorted input values.','sort() orders values; decreasing = TRUE reverses the default order.'])
add(2,'Speed of Vectorized Operations','Vectorization and an equivalent loop','Both approaches multiply matching elements.\nVectorization expresses the operation directly.',code='N <- 100\na <- rnorm(N)\nb <- rnorm(N)\nc <- a * b\nd <- rep(NA, N)\nfor (i in 1:N) {\n  d[i] <- a[i] * b[i]\n}',comments=['rnorm() generates artificial normal draws; rep() allocates missing entries.','The for loop fills each position; a * b does the operation at once.'])
add(2,'Speed of Vectorized Operations','Comparing execution times','Use 100,000 values, as in the lesson.\nCompare measured execution time on your own computer.\nTimings vary between computers and runs.',code='N <- 100000\na <- rnorm(N); b <- rnorm(N)\nvectorized_time <- system.time({ c <- a * b })\nde_vectorized_time <- system.time({\n  d <- rep(NA, N)\n  for (i in 1:N) d[i] <- a[i] * b[i]\n})\nprint(vectorized_time)\nprint(de_vectorized_time)',comments=['rnorm() generates artificial inputs; rep() allocates the loop result.','system.time() measures CPU and elapsed time; print() displays those timings.'])
add(2,'Other Data Structures (Matrix, Array, List and Data frames)','Beyond a vector','The same values can be organized in different structures.\nChoose a structure that fits the question and the data.',hint='Next: matrices, arrays, lists, and data frames.')
add(2,'Matrices','Matrices','A matrix has rows and columns and one underlying type.\nR fills columns first by default.',code='matrix_data <- matrix(1:6, nrow = 3, ncol = 2)',comments=['matrix() arranges six sequential values into a rectangular object.','nrow = 3 and ncol = 2 specify three rows and two columns.'],hint='The source also mentions an NBA example but supplies no linked file.')
add(2,'Arrays','Arrays','An array can have more than two dimensions.',code='array_data <- array(1:24, dim = c(3, 4, 2))',comments=['array() organizes values into the dimensions supplied by c().','dim = c(3, 4, 2) gives three rows, four columns, and two layers.'])
add(2,'Lists','Lists','A list can hold objects of different types and lengths.',code='list_data <- list(\n  name = "Alice", age = 25, scores = c(90, 80, 85))\nprint(list_data[1])',comments=['list() keeps unlike objects together; c() combines the score values.','[1] returns a sublist; [[1]] extracts its first element; print() displays it.'])
add(2,'Data Frames','Data frames','A data frame is a rectangular collection of columns.\nColumns can have different types. Rows align observations.',code='df <- data.frame(\n  Name = c("Alice", "Bob"),\n  Age = c(25, 30),\n  Weight = c(55.5, 85.7)\n)',comments=['c() supplies the column values; data.frame() combines them into a table.','Keep one observation per row; the source does not state Weight units.'])
add(2,'R built-in datasets','Built-in practice datasets','Use data() to browse datasets and ?mtcars for help.\nView() opens a table viewer in RStudio.\nmtcars is the lesson example for table access.',code='data()\n?mtcars\nView(trees)',comments=['data() lists available datasets; ? opens the named help page.','View() opens an interactive viewer and is a manual RStudio step.'],hint='mpg means miles per US gallon; wt is vehicle weight in 1,000 lb.')
add(2,'Access Data Frame Elements','Column access: vector or table','mtcars$mpg extracts a vector.\nmtcars["mpg"] keeps a one-column data frame.',code='miles_per_hour <- mtcars$mpg\nprint(miles_per_hour)\nmiles_per_hour <- mtcars["mpg"]\nprint(miles_per_hour)',comments=['$ extracts a column vector; ["mpg"] retains a data frame.','print() shows each result; the legacy name is misleading: mpg is fuel economy.'],hint='The original object name is retained here, but mpg is not miles per hour.')
add(2,'Access Data Frame Elements','Row and column indexing','Use table[rows, columns].\nA blank dimension keeps all its entries.',code='subset_df <- mtcars[c("mpg", "cyl")]\nfirst_row <- mtcars[1, ]\nmpg <- mtcars[2, "mpg"]\nmtcars[5:7, ]\nmtcars[20:30, 8:10]',comments=['c() selects several columns; : creates consecutive index ranges.','With a comma, the first position selects rows and the second selects columns.'])
add(2,'Access Data Frame Elements','Indexing variations','One index on a data frame selects columns.\nA comma separates row selection from column selection.',code='mtcars[2:9]\nmtcars[, 2:9]\nmtcars[2, 9]\nmtcars[2:9, ]\nmtcars[c(2, 6)]\nmtcars[, c(2, 6)]\nmtcars[c(2, 6), ]\nmtcars[2:6]\nmtcars[5, ]',comments=[': generates consecutive positions; c() combines individual positions.','Compare each one-index form with the corresponding row/column form.'])
add(2,'Access Data Frame Elements','Row names and identifiers','Row names can identify a record.\nThey can also be copied into an explicit column.',code='car_names <- rownames(mtcars)\nfirst_car_name <- rownames(mtcars)[1]\ndatsun_710 <- mtcars["Datsun 710", ]\nmtcars$car_brand <- rownames(mtcars)\nhead(mtcars)\nmtcars["Fiat 128", ]',comments=['rownames() retrieves record labels; [1] selects the first label.','head() previews six rows; these row names identify models, not just brands.'])
add(2,'Access Data Frame Elements','Conditions and table dimensions','A logical row condition selects observations.\nFor data frames, length() counts columns.\nnrow() and ncol() explicitly count rows and columns.',code='m <- mtcars[mtcars$cyl == 4, ]\nlength(m)\nlength(mtcars[, 1])\nnrow(mtcars)\nncol(mtcars)\nnrow(mtcars[mtcars$am == 0, ])',comments=['== creates logical conditions; am = 0 denotes automatic transmission.','length() counts vector elements or table columns; nrow()/ncol() count dimensions.'])
add(2,'Access Data Frame Elements','Filtering against a calculated value','A condition can compare values with a computed summary.',code='mean(c(40, 60, 40, 60))\nmtcars[mtcars$mpg < mean(mtcars$mpg), ]\nmore_than_4_cyl <- subset(mtcars, cyl > 4)\nprint(more_than_4_cyl)',comments=['c() combines values; mean() calculates their average.','subset() selects matching rows using column names; print() displays them.'])
add(2,'Access Data Frame Elements','Student table: construction','The lesson combines aligned name, age, and gender vectors.',code='name <- c("John", "Alice", "Bob", "Eva")\nage <- c(23, 25, 30, 22)\ngender <- c("Male", "Female", "Male", "Female")\nstudents <- data.frame(name, age, gender)\nprint(students)',comments=['c() builds the three vectors; data.frame() aligns them by row.','print() displays the illustrative table used in the next access examples.'])
add(2,'Access Data Frame Elements','Student table: access and filter','Compare named columns, positions, and a logical row filter.',code='print(students$age)\nprint(students["gender"])\nprint(students[2, 1])\nprint(students[3, ])\nprint(students[, 2])\nolder_students <- students[students$age > 23, ]\nprint(older_students)',comments=['$ extracts a vector; ["gender"] retains a one-column table.','[row, column] chooses positions; > 23 marks rows retained by the filter.'])
add(2,'Miscellaneous Related Topics - مواضيع متفرقة ذات علاقة','Output, input, and the workspace','After storing and accessing values, consider how to interact with R.\nDisplay results, request input, and manage saved objects.')
add(2,'Printing Output','Printing and joining text','print() displays an R object.\ncat() writes values together as output.\npaste() returns joined character strings.',code='print("Hello, World!")\ncat("Hello,", "World!", "\\n")\nresult <- paste("Hello", "World", sep = " ")\nprint(result)\ncat(result, "\\n")',comments=['paste() uses sep between inputs; print() displays the resulting value.','cat() writes text; "\\n" explicitly adds a new output line.'])
add(2,'Requesting user input','Interactive input','Try this in the Console rather than an unattended Quarto render.',code='name <- readline("Please enter your name: ")\ncat("Your name is:", name)',comments=['readline() waits for an interactive line and returns character text.','cat() writes the response with the supplied label.'])
add(2,'Values Assignments in R','Assignment syntax','<- is the preferred course style.\n-> assigns toward the right. = can also assign.\n== compares values rather than assigning.',code='x <- 1\n1 -> x\nx = 1\n# Intentional invalid assignment:\n1 = x',comments=['The receiving side of an assignment must be an assignable object.','The final line intentionally fails because literal 1 cannot receive a value.'])
add(2,'List Memory, Clean Memory','Inspecting and clearing the workspace','ls() lists object names. rm() removes specified objects.\nThe RStudio broom or workspace menu also clears objects.\nRestart R when you need a fresh session.',code='x <- 1\ny <- 2\nls()\nrm(x, y)\nls()\nrm(list = ls())',comments=['ls() returns names; rm(x, y) removes only those named objects.','rm(list = ls()) clears the current environment deliberately.'],hint='Restart shortcut: Ctrl+Shift+F10; use Cmd+Shift+F10 on macOS.')
add(2,'Flow of Control','Flow of control','So far, code has applied operations to objects.\nLoops repeat steps. Conditions choose steps.\nFunctions package steps for reuse.',hint='Begin with repetition, then branching, then functions.')
add(2,'The `for` Loop','The for loop','A for loop visits each value in a sequence.',code='numbers <- 1:5\nfor (num in numbers) {\n  print(num^2)\n}',comments=['1:5 supplies five values; for assigns each in turn to num.','^2 squares the current value; print() displays each square.'])
add(2,'The `for` Loop','Loop indexing practice','Replace the stars so the loop visits every position of x.\nKeep the exercise unfinished until students attempt it.',code='x <- 50:60\nfor (i in *:*) {\n  print(x[i])\n}',comments=['This is a practice template, not executable R until the stars are replaced.','x[i] selects a position; print() displays the value in that position.'])
add(2,'The `while` Loop','The while loop','Repeat while a condition remains TRUE.\nUpdate the value used in the condition so the loop can stop.',code='countdown <- 5\nwhile (countdown > 0) {\n  print(paste("Counting down:", countdown))\n  countdown <- countdown - 1\n}\nprint("Lift off!")',comments=['while tests the condition before each repetition.','paste() joins the label and value; print() displays it; subtraction updates it.'])
add(2,'The `repeat` Loop','The repeat loop','repeat keeps running until break exits.\nThe example searches above 100 for a multiple of 13.',code='number <- 101\nrepeat {\n  if (number %% 13 == 0) {\n    print(paste("Found a number divisible by 13:", number))\n    break\n  }\n  number <- number + 1\n}',comments=['%% calculates a remainder; == 0 tests exact divisibility.','if chooses the stopping branch; paste()/print() show it; break exits the loop.'])
add(2,'Nested Loops','Nested loops','An outer loop can visit rows while an inner loop visits columns.',code='my_matrix <- matrix(1:9, nrow = 3)\nfor (row in 1:nrow(my_matrix)) {\n  for (col in 1:ncol(my_matrix)) {\n    my_matrix[row, col] <- my_matrix[row, col] * 2\n  }\n}\nprint(my_matrix)',comments=['matrix() fills columns first; nrow()/ncol() supply the index bounds.','Each nested-loop pass doubles one cell; print() displays the final matrix.'])
add(2,'Conditional Branching in R','Conditional branching','Conditions choose which code to run.\nAn if condition must resolve to one nonmissing logical value.\nUse else and else if to handle alternative cases.')
add(2,'The `if` Statement','A single if condition','Run the body when the condition is TRUE.',code='number <- 5\nif (number > 0) {\n  print("The number is positive.")\n}',comments=['if checks whether number is greater than zero.','print() runs only when that condition is TRUE.'])
add(2,'The `else` Statement','An alternative with else','else handles the remaining case.',code='number <- -3\nif (number > 0) {\n  print("The number is positive.")\n} else {\n  print("The number is not positive.")\n}',comments=['if selects the first branch only for a positive number.','else selects the alternative; print() displays its message.'])
add(2,'The `else if` Statement','Several conditions with else if','Test conditions in sequence.\nThe first TRUE branch runs.',code='number <- 0\nif (number > 0) {\n  print("The number is positive.")\n} else if (number < 0) {\n  print("The number is negative.")\n} else {\n  print("The number is zero.")\n}',comments=['else if tests a second condition only when the first is FALSE.','The final else covers zero here; print() displays the selected message.'])
add(2,'The `switch` Statement','Matching labels with switch()','Choose a branch by matching a character value.',code='day <- "Tue"\nswitch(day,\n  "Mon" = {print("Start of the work week")},\n  "Tue" = {print("Second day of the work week")},\n  "Wed" = {print("Middle of the work week")},\n  "Thu" = {print("Approaching the end")},\n  "Fri" = {print("Last day of the work week")},\n  {print("It must be the weekend")}\n)',comments=['switch() selects the branch matching day; print() displays its text.','The last unnamed branch is a fallback for an unmatched character label.'],hint='These are the lesson labels, not a calendar convention for every country.')
add(2,'Creating Functions in R','Creating reusable functions','A function bundles a calculation under a name.\nArguments supply inputs. The function body performs the work.\nThe result can be reused by later code.')
add(2,'Basic Function Structure','Function inputs, body, and result','The example adds two supplied numbers.',code='add_two_numbers <- function(a, b) {\n  result <- a + b\n  return(result)\n}\nprint(add_two_numbers(5, 3))',comments=['function(a, b) defines two inputs; return() chooses the output.','add_two_numbers() calls that calculation; print() displays its result.'])
add(2,'Function Arguments and Return Values','Arguments and return values','A function returns its last evaluated expression by default.\nreturn() explicitly selects a result or returns early.',code='greet_person <- function(name) {\n  greeting <- paste("Hello,", name)\n  return(greeting)\n}\nprint(greet_person("Alice"))',comments=['function() defines the input; paste() joins text using a space by default.','return() passes the greeting back; print() shows the call result.'])
add(2,'Default Argument Values','Default arguments','A default value makes an argument optional.',code='raise_to_power <- function(base, exponent = 2) {\n  result <- base ^ exponent\n  return(result)\n}\nprint(raise_to_power(4))\nprint(raise_to_power(4, 3))',comments=['function() sets exponent = 2 unless the caller supplies another value.','^ computes the power; return() passes it back; print() shows 16 and 64.'])
add(2,'Returning Multiple Values','Returning several results','Return a named list to keep related results together.',code='calculate_stats <- function(numbers) {\n  mean_val <- mean(numbers)\n  sum_val <- sum(numbers)\n  return(list(mean = mean_val, sum = sum_val))\n}\nstats <- calculate_stats(c(1, 2, 3, 4, 5))\nprint(stats)',comments=['mean() averages and sum() totals; list() combines the named results.','function()/return() define the calculation; c() supplies inputs; print() shows it.'])
add(2,'Anonymous Functions','Anonymous functions','A short function can be supplied directly to another function.',code='numbers <- 1:5\ndoubled_numbers <- sapply(numbers, function(x) x * 2)\nprint(doubled_numbers)',comments=['function(x) x * 2 defines a calculation without a separate function name.','sapply() applies it to each value and simplifies compatible results; print() shows them.'])
add(2,'Scope and Environment','Local scope','An object created inside a function is local to that call.\nReturn the result when you want to use it outside.',code='increment <- function(x) {\n  y <- x + 1\n  return(y)\n}\nincremented_value <- increment(5)\nprint(incremented_value)',comments=['function() creates local x and y; return() exposes the computed result.','increment() performs the call; print() shows it; y is not created outside.'],hint='Continue with the basic-concepts exercises in Quarto.')
divider(3,'Lesson 3: Data manipulation with dplyr','Use the R foundations to prepare and summarize the textbook table.','Purpose and data')
add(3,'Purpose and data','Restaurant case','Select restaurants by quality and price, then summarize prices by quality.\nOne row is one restaurant, identified by restaurant_id.\nPrices are in USD. Ratings: Good, Very Good, Excellent.',arabic='نختار المطاعم حسب الجودة والسعر، ثم نلخّص الأسعار حسب الجودة.\nيمثّل كل صف مطعمًا واحدًا يحدّده restaurant_id.\nالأسعار بالدولار الأمريكي. التقييمات: جيد، وجيد جدًا، وممتاز.',hint='Historical textbook data; statistical interpretation continues in Module 2.')
add(3,'Purpose and data','Load the checked CSV','Load dplyr and read the teaching CSV.\nWork from the 20261 RStudio project.',code='library(dplyr)\nrestaurants <- read.csv("data/module02/restaurant_ratings.csv")\nhead(restaurants)\nglimpse(restaurants)',comments=['library() loads dplyr; read.csv() reads a CSV with names in its first row.','head() previews six rows; glimpse() shows dimensions, types, and sample values.'],hint='Keep the source CSV unchanged; save derived tables under new names.')
add(3,'Purpose and data','Recreate the ordered rating','A CSV stores labels but cannot preserve R factor metadata.\nExplicitly record the category order after import.',code='restaurants$quality_rating <- factor(\n  restaurants$quality_rating,\n  levels = c("Good", "Very Good", "Excellent"),\n  ordered = TRUE)',comments=['factor() records categories; c() supplies their permitted order.','ordered = TRUE marks ordinal levels; $ chooses the rating column.'])
add(3,'Select columns','Select columns','select() retains named variables.\nSelecting variables does not filter observations.',code='prices <- restaurants |>\n  select(restaurant_id, meal_price_usd)\nhead(prices)',comments=['|> passes the table to select(), which retains these two columns.','head() previews six rows of the newly saved prices table.'])
add(3,'Filter rows','Filter rows with AND','Keep Excellent restaurants with a meal price of at least USD 30.',code='selected <- restaurants |>\n  filter(quality_rating == "Excellent", meal_price_usd >= 30)\nhead(selected)\nnrow(selected)',comments=['filter() keeps TRUE conditions; a comma combines conditions with AND.','head() previews the result; nrow() counts its retained observations.'],hint='A condition evaluating to NA does not pass filter().')
add(3,'Filter rows','Membership and OR conditions','%in% tests membership in a set.\nUse | when either of two conditions is enough.',code='restaurants |>\n  filter(quality_rating %in% c("Good", "Very Good"),\n         meal_price_usd < 20) |>\n  head()',comments=['c() supplies allowed categories; %in% tests membership in that set.','The comma also requires price < USD 20; head() previews six matches.'])
add(3,'Pipes and readable steps','A readable pipeline','Read the sequence from top to bottom.\nEach result becomes the input to the next operation.',code='restaurants |>\n  filter(meal_price_usd >= 30) |>\n  select(restaurant_id, quality_rating, meal_price_usd) |>\n  arrange(desc(meal_price_usd), restaurant_id) |>\n  head(5)',comments=['filter() chooses rows and select() chooses columns.','arrange() sorts; desc() reverses price order; head(5) retains five rows.'],hint='dplyr also supports %>%; use a consistent pipe style.')
add(3,'Arrange and create variables','Sorting and derived variables','arrange() sorts rows. mutate() creates or replaces columns.\nDerived labels do not correct the original measurements.',code='prepared <- restaurants |>\n  mutate(price_at_least_30 = meal_price_usd >= 30,\n    price_band = cut(meal_price_usd,\n      c(10, 20, 30, 40, 50), right = FALSE)) |>\n  arrange(quality_rating, meal_price_usd)\nhead(prepared)',comments=['cut() uses the breakpoints in c(); right = FALSE gives [lower, upper) bands.','mutate() adds columns; arrange() sorts rows; head() displays a preview.'],hint='10 is included in [10,20); 50 falls outside these specified bands.')
add(3,'Count categories and summarize groups','Count categories','count() counts observations in each category.',code='restaurants |>\n  count(quality_rating, name = "restaurants")',comments=['|> passes the data to count(), which groups and counts category rows.','name = "restaurants" names the frequency column in the returned table.'])
add(3,'Count categories and summarize groups','Summarize within groups','group_by() defines groups for the following calculations.\nsummarise() returns the requested group statistics.',code='group_summary <- restaurants |>\n  group_by(quality_rating) |>\n  summarise(n = n(),\n    mean_price_usd = mean(meal_price_usd),\n    median_price_usd = median(meal_price_usd),\n    .groups = "drop")\ngroup_summary',comments=['n() counts rows; mean() averages prices; median() finds their middle value.','group_by()/summarise() calculate by rating; .groups = "drop" ungroups the result.'])
add(3,'Count categories and summarize groups','Validate totals and grouping','Check that group counts add to the original row count.\nGrouping metadata affects later calculations.\nungroup() removes grouping explicitly when needed.',code='stopifnot(sum(group_summary$n) == nrow(restaurants))',comments=['sum() totals the saved counts; nrow() gives the original table size.','stopifnot() stops on a failed condition and prints nothing when it passes.'],hint='Summarize actual prices; avoid averaging arbitrary numeric category codes.')
add(3,'Missing values and duplicates','Missing values and duplicate identifiers','Check missingness before deciding which observations to omit.\nEqual prices do not make two restaurant records duplicates.',code='colSums(is.na(restaurants))\nanyDuplicated(restaurants$restaurant_id)',comments=['is.na() flags missing values; colSums() counts them in each column.','anyDuplicated() returns 0 if none occur, or the first duplicate position.'],hint='Use na.rm = TRUE only when the omitted observations and consequences are clear.')
add(3,'Join on a key','A lookup derived from the summary','Use the shared quality_rating key to attach group medians.',code='lookup <- group_summary |>\n  select(quality_rating, group_median_usd = median_price_usd)\nwith_group_median <- restaurants |>\n  left_join(lookup, by = "quality_rating")\nhead(with_group_median)',comments=['select() retains the key and renames the median column for the lookup.','left_join() attaches matching lookup rows; by specifies the key; head() previews it.'])
add(3,'Join on a key','Join checks','A unique lookup key should preserve the 300 restaurant rows.\nRepeated matching keys can multiply rows.\ninner_join() keeps matches; left_join() retains left-table observations.',code='stopifnot(\n  nrow(with_group_median) == nrow(restaurants),\n  !anyNA(with_group_median$group_median_usd))',comments=['nrow() compares row counts; anyNA() detects missing joined medians.','! negates the missingness result; stopifnot() halts if either check fails.'])
add(3,'Reshape a summary','Reshape from wide to long','pivot_longer() moves selected columns into name/value rows.\nThe rating remains the identifier for each group.',code='library(tidyr)\nlong_summary <- group_summary |>\n  select(quality_rating, mean_price_usd, median_price_usd) |>\n  pivot_longer(-quality_rating,\n    names_to = "measure", values_to = "price_usd")\nlong_summary',comments=['library() loads tidyr; select() retains the summary columns to reshape.','pivot_longer() names new columns via names_to/values_to; -rating excludes the key.'])
add(3,'Reshape a summary','Reshape from long to wide','pivot_wider() restores measure columns when keys identify cells.',code='long_summary |>\n  pivot_wider(names_from = measure, values_from = price_usd)',comments=['pivot_wider() makes columns from values in the measure column.','names_from chooses column names; values_from supplies their cell values.'])
add(3,'Export a derived result','Export a derived summary','Write report outputs to _output/, separate from the input CSV.\nRun file-writing commands manually when an export is wanted.',code='dir.create("_output", showWarnings = FALSE)\nwrite.csv(group_summary,\n  "_output/restaurant-price-summary.csv", row.names = FALSE)',comments=['dir.create() prepares the folder; showWarnings = FALSE suppresses existing-folder warnings.','write.csv() exports the table; row.names = FALSE omits an extra row-number column.'],hint='Continue with the matching dplyr exercises in Quarto.')
divider(4,'Lesson 4: Visualization with ggplot2','The prepared table now becomes input to a layered graphic.','Introduction to ggplot2')
add(4,'What is ggplot2?','The grammar of graphics','A plot combines data, mappings, and layers.\nBuild it gradually, checking what each added part changes.\nThe same framework supports many chart types.')
add(4,'What is ggplot2?','Plot components','Data: the table to display.\nAesthetics: map variables to position, color, size, or shape.\nGeometries: represent observations as points, lines, bars, and more.\nScales and coordinates control how values appear.')
add(4,'What is ggplot2?','Additional plot components','Statistical transformations count, bin, smooth, or summarize.\nFacets separate groups into panels.\nThemes control nondata appearance such as fonts and backgrounds.',hint='These components will appear in the examples that follow.')
add(4,'What is ggplot2?','The lesson component illustration','Conceptual illustration from the Quarto lesson.',image='20261/assets/module01/ggplot-components.png',hint='Source: existing lesson asset; original external attribution is not stated.')
add(4,'What is ggplot2?','Layering illustration','The Quarto lesson also illustrates how graphical layers combine.',image='20261/assets/module01/grammar-of-graphics.gif',hint='Static slide frame; open the Quarto lesson to view the animation.')
add(4,'Step 1: Loading ggplot2 and Data','Step 1: load the package and data','Use the lesson built-in mtcars dataset.\nOne row describes a car model.',code='library(ggplot2)\ndata(mtcars)',comments=['library() makes ggplot2 functions available in this R session.','data() loads mtcars; mpg is miles per US gallon and wt is weight in 1,000 lb.'])
add(4,'Step 2: Initiating a ggplot Object','Step 2: define data and mappings','ggplot() starts the plot.\naes() maps weight to x and fuel economy to y.',code='ggplot(data = mtcars, aes(x = wt, y = mpg))',comments=['ggplot() selects the table; aes() specifies the variable mappings.','This defines the plot framework; a geometry is still needed to draw observations.'])
add(4,'Step 3: Adding Geometric Objects','Step 3: add a geometry','Use + to add a layer to a ggplot.\nDifferent geometries represent different kinds of questions.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point()\nggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_line()\nggplot(mtcars, aes(x = factor(cyl))) +\n  geom_bar()',comments=['ggplot()/aes() define mappings; geom_point() draws paired observations.','geom_line() joins x order; factor() marks categories; geom_bar() counts rows.'],hint='Connecting car models illustrates line syntax; it does not create a time sequence.')
add(4,'Step 4: Enhancing the Plot with Labels and Titles','Step 4: add meaningful labels','labs() supplies chart and axis titles.\nState measurement units explicitly.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point() +\n  labs(title = "Car Weight vs. Fuel Efficiency",\n       x = "Weight of Car (1000 lbs)",\n       y = "Miles per Gallon")',comments=['ggplot()/aes()/geom_point() draw the paired observations.','labs() labels axes and the title; wt units are 1,000 lb and mpg uses US gallons.'],plot='labels')
add(4,'Step 5: Customizing Colors and Shapes','Step 5: map categories to appearance','Mapping inside aes() varies appearance by a variable.\nUse color and shape together to distinguish cylinder groups.',code='ggplot(mtcars, aes(x = wt, y = mpg,\n    color = factor(cyl), shape = factor(cyl))) +\n  geom_point() +\n  labs(color = "Number of Cylinders",\n       shape = "Number of Cylinders")',comments=['factor() treats cylinder counts as categories inside aes().','geom_point() draws points; labs() names the color and shape legends.'],plot='color')
add(4,'Step 6: Adjusting X and Y Axis Limits','Step 6: axis limits','Scale limits can remove observations outside the displayed range.\nInterpret the remaining data with this consequence in mind.',code='ggplot(mtcars, aes(x = wt, y = mpg,\n    color = factor(cyl))) +\n  geom_point() +\n  xlim(2, 5) +\n  ylim(10, 35)',comments=['ggplot()/aes() map data; factor() groups cylinders; geom_point() draws points.','xlim()/ylim() set scale limits and can discard rows outside them.'],hint='The shown ranges are weight 2,000–5,000 lb and fuel economy 10–35 mpg.',plot='limits')
add(4,'Step 6: Adjusting X and Y Axis Limits','Step 6: scale labels and breaks','Scales control axis names, breaks, and other display choices.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point() +\n  scale_x_continuous(name = "Weight (1000 lbs)",\n    breaks = seq(2, 5, by = 0.5)) +\n  scale_y_continuous(name = "Miles per Gallon")',comments=['ggplot()/aes()/geom_point() create the scatterplot.','scale_*_continuous() customizes axes; seq(..., by = 0.5) requests spaced ticks.'])
add(4,'Step 7: Modifying the Legend','Step 7: adjust the legend','A legend explains a mapped visual property.',code='ggplot(mtcars, aes(x = wt, y = mpg,\n    color = factor(cyl))) +\n  geom_point() +\n  labs(color = "Number of Cylinders") +\n  guides(color = guide_legend(title = "Cylinders"))',comments=['factor()/aes() map cylinder categories; geom_point() draws observations.','labs() names mappings; guides()/guide_legend() customize the color legend.'])
add(4,'Step 8: Adding More Geoms','Step 8: a fitted line for each group','A global color mapping also groups the fitted lines.',code='ggplot(mtcars, aes(x = wt, y = mpg,\n    color = factor(cyl))) +\n  geom_point() +\n  geom_smooth(method = "lm", se = FALSE)',comments=['ggplot()/aes()/factor() map cylinder groups to all inherited layers.','geom_smooth(method = "lm") fits lines; se = FALSE hides mean-trend bands.'],plot='group-lines')
add(4,'Step 8: Adding More Geoms','Step 8: one fitted line for all observations','Move the color mapping into the points layer.\nThe fitted line then uses the combined observations.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point(aes(color = factor(cyl))) +\n  geom_smooth(method = "lm", se = FALSE)',comments=['aes()/factor() inside geom_point() color only the points by cylinder group.','geom_smooth() inherits x/y only; lm fits one line and se = FALSE hides its band.'],plot='one-line')
add(4,'Faceting','Faceting with facet_wrap()','Split the observations into panels by cylinder count.\nCompare the same variables across groups.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point() +\n  facet_wrap(~ cyl)',comments=['ggplot()/aes()/geom_point() define the same scatterplot in each panel.','facet_wrap(~ cyl) makes one panel per distinct cylinder count.'],plot='wrap')
add(4,'Faceting','Faceting with facet_grid()','Use engine type for panel rows and transmission for columns.\nPanel comparisons require attention to scales.',code='ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point() +\n  facet_grid(vs ~ am)',comments=['ggplot()/aes()/geom_point() draw the observations in each panel.','facet_grid(vs ~ am) puts engine type in rows and transmission in columns.'],plot='grid')
divider(4,'Geometry examples','Keep the same plotting grammar and change the geometry.\nThe following examples follow the Quarto order.','Demonstrating Different GEOM Types')

# Every original geometry has a visible explanation, executable example, and rendered result.
GEOMS=[
('1. **`geom_point()`** - Scatter plot','1. Scatter plot','Numerical x and y. Each point is one observation.\nLook for direction, clusters, unusual points, and curvature.',
 'ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_point()', ['ggplot() chooses data; aes() maps weight and fuel economy to x and y.','geom_point() draws one point for each row.'],'scatter','Business use: advertising and sales; customer age and preference.','استخدام تجاري: الإعلان والمبيعات؛ وعمر العميل وتفضيلاته.'),
('2. **`geom_line()`** - Line plot','2. Line plot','Use ordered x with numerical y.\nThe lesson connects cars in weight order, which is not a time series.',
 'ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_line() + geom_point()', ['ggplot()/aes() map the two variables; geom_point() shows original observations.','geom_line() joins observations in x order within groups.'],'line','Business use: revenue, stock prices, or website traffic over time.','استخدام تجاري: الإيرادات أو أسعار الأسهم أو زيارات الموقع عبر الزمن.'),
('3. **`geom_smooth()`** - Smoothed line plot','3. Fitted trend','Numerical x and y. A fitted trend summarizes a relationship.\nOutliers remain relevant to the fit and interpretation.',
 'ggplot(mtcars, aes(x = wt, y = mpg)) +\n  geom_smooth(method = "lm")', ['ggplot()/aes() define the paired data; geom_smooth() adds a fitted trend.','method = "lm" fits a line; the default band concerns the estimated mean trend.'],'smooth','Business use: explore broad trends in fluctuating financial or sales data.','استخدام تجاري: استكشاف الاتجاهات العامة في البيانات المالية أو بيانات المبيعات المتقلبة.'),
('4. **`geom_bar()`** - Bar chart','4. Category counts','Categorical x. Bar height counts observations by default.\nFor precomputed quantities, use geom_col().',
 'ggplot(mpg, aes(x = class)) +\n  geom_bar()', ['ggplot()/aes() map the vehicle class to x.','geom_bar() counts rows in each category by default.'],'bar','Business use: compare product categories, customers by region, or departments.','استخدام تجاري: مقارنة فئات المنتجات أو العملاء حسب المنطقة أو الأقسام.'),
('5. **`geom_histogram()`** - Histogram','5. Numerical distribution','Numerical x is divided into bins.\nBin choices affect the apparent shape.',
 'ggplot(mtcars, aes(x = mpg)) +\n  geom_histogram(bins = 10)', ['ggplot()/aes() map fuel economy; geom_histogram() counts observations in bins.','bins = 10 requests ten bins; compare other bin choices before interpreting shape.'],'histogram','Business use: distributions of transaction sizes, customer ages, or response times.','استخدام تجاري: توزيعات قيم المعاملات أو أعمار العملاء أو أزمنة الاستجابة.'),
('6. **`geom_boxplot()`** - Boxplot','6. Grouped boxplots','Compare a numerical distribution across categories.\nMedian and quartiles summarize the center and spread.\nBeyond-whisker points flag observations for inspection.',
 'ggplot(mpg, aes(x = class, y = hwy)) +\n  geom_boxplot()', ['ggplot()/aes() map class groups and highway miles per US gallon.','geom_boxplot() summarizes each group and marks beyond-whisker observations.'],'boxplot','Business use: compare satisfaction by branch or sales distributions by region.','استخدام تجاري: مقارنة الرضا حسب الفرع أو توزيعات المبيعات حسب المنطقة.'),
('7. **`geom_area()`** - Area plot','7. Area plot','Fill the area below a sequence of numerical values.\nThe example shows unemployment levels over time, not a rate.',
 'ggplot(economics, aes(x = date, y = unemploy)) +\n  geom_area()', ['ggplot()/aes() map date and unemployment counts from economics.','geom_area() fills beneath the line; unemploy is measured in thousands of persons.'],'area','Business use: show cumulative sales or contributions of product categories over time.','استخدام تجاري: عرض المبيعات التراكمية أو مساهمات فئات المنتجات عبر الزمن.'),
('8. **`geom_density()`** - Density plot','8. Density plot','A smooth estimate of a numerical distribution.\nThe curve shows density rather than raw counts.',
 'ggplot(mpg, aes(x = hwy)) +\n  geom_density()', ['ggplot()/aes() map highway miles per US gallon.','geom_density() estimates a density curve; its smoothing choice affects shape.'],'density','Business use: compare pricing patterns or income distributions in customer segments.','استخدام تجاري: مقارنة أنماط الأسعار أو توزيعات الدخل في شرائح العملاء.'),
('9. **`geom_violin()`** - Violin plot','9. Violin plot','Compare density shapes within categories.\nA plain violin does not automatically draw boxplot summaries.',
 'ggplot(mpg, aes(x = class, y = hwy)) +\n  geom_violin()', ['ggplot()/aes() map class and highway fuel economy.','geom_violin() draws a mirrored density for each category.'],'violin','Business use: compare customer satisfaction or product ratings across categories.','استخدام تجاري: مقارنة رضا العملاء أو تقييمات المنتجات بين الفئات.'),
('10. **`geom_col()`** - Column chart','10. Columns for supplied values','geom_col() uses y values as supplied.\nRepeated categories stack by default. It does not calculate a mean.',
 'ggplot(mpg, aes(x = class, y = hwy)) +\n  geom_col()', ['ggplot()/aes() map the original row values to categories and y.','geom_col() uses those values directly and stacks repeated class rows by default.'],'column','Business use: compare monthly revenue, category sales, or inventory levels.','استخدام تجاري: مقارنة الإيرادات الشهرية أو مبيعات الفئات أو مستويات المخزون.'),
('11. **`geom_tile()`** - Heatmap','11. Heatmap','Two grid dimensions identify cells; fill encodes a third value.\nThese are simulated values rather than observed business data.',
 'data <- expand.grid(Var1 = letters[1:10], Var2 = 1:10)\ndata$value <- runif(100, min = 0, max = 100)\nggplot(data, aes(x = Var1, y = Var2, fill = value)) +\n  geom_tile()', ['expand.grid() creates combinations; runif() simulates 100 uniform values from 0 to 100.','ggplot()/aes() map the cells and fill; geom_tile() draws the rectangular cells.'],'tile','Business use: day/hour traffic, region/product sales, or a correlation matrix.','استخدام تجاري: الزيارات حسب اليوم والساعة أو المبيعات حسب المنطقة والمنتج أو مصفوفة الارتباط.'),
('12. **`geom_text()`** and **`geom_label()`** - Adding text/labels','12. Text and labels','Identify observations with their row labels.\ngeom_label() adds a background behind the text.',
 'ggplot(mtcars, aes(x = wt, y = mpg,\n    label = rownames(mtcars))) +\n  geom_text(vjust = -0.5)\nggplot(mtcars, aes(x = wt, y = mpg,\n    label = rownames(mtcars))) +\n  geom_label(vjust = -0.5)', ['rownames() provides model labels; ggplot()/aes() map labels and coordinates.','geom_text()/geom_label() add text; vjust = -0.5 moves it above its anchor.'],'text','Business use: label unusual points, important observations, or chart totals.','استخدام تجاري: تسمية النقاط غير المعتادة أو المشاهدات المهمة أو المجاميع على الرسم.'),
('13. **`geom_ribbon()`** - Ribbon plot','13. Ribbon plot','A ribbon fills the interval between ymin and ymax.\nThe lesson uses an artificial sine trend plus random noise.\nIts fixed ±0.5 band is illustrative, not a calculated confidence interval.',
 'df <- data.frame(x = 1:100)\ndf$y <- sin(df$x / 10) * 2 + rnorm(100, sd = 0.5)\ndf$ymax <- df$y + 0.5\ndf$ymin <- df$y - 0.5\nggplot(df, aes(x = x, ymin = ymin, ymax = ymax, y = y)) +\n  geom_ribbon(alpha = 0.4) + geom_line()', ['data.frame() creates x; sin() and rnorm() create an artificial noisy trend.','aes() maps bounds; geom_ribbon() fills them with alpha transparency; geom_line() adds y.'],'ribbon','Business use: display forecast ranges or statistically calculated uncertainty bands.','استخدام تجاري: عرض نطاقات التنبؤ أو نطاقات عدم اليقين المحسوبة إحصائيًا.'),
('14. **`geom_jitter()`** - Jitter plot','14. Jittered points','Small display offsets reveal overlapping observations.\nThe source measurements remain unchanged.',
 'ggplot(mpg, aes(x = class, y = hwy)) +\n  geom_jitter(width = 0.2)', ['ggplot()/aes() map class and highway fuel economy.','geom_jitter() offsets plotted points; width = 0.2 controls horizontal jitter.'],'jitter','Business use: reveal overlapping transactions or customer ratings.','استخدام تجاري: إظهار المعاملات أو تقييمات العملاء التي تتداخل نقاطها على الرسم.'),
('15. **`geom_point()`** - Bubble plot','15. Bubble plot','Point position encodes two variables. Point size encodes horsepower.\nTransparency helps show overlap.',
 'ggplot(mtcars, aes(x = wt, y = mpg, size = hp)) +\n  geom_point(alpha = 0.5) +\n  scale_size_continuous(range = c(1, 20)) +\n  labs(size = "Horsepower") +\n  theme_minimal()', ['ggplot()/aes() map variables; geom_point(alpha = 0.5) adds translucent points.','scale_size_continuous()/c() set size range; labs() labels it; theme_minimal() styles the plot.'],'bubble','Business use: advertising and sales with transaction counts, or unit metrics with size.','استخدام تجاري: الإعلان والمبيعات مع عدد المعاملات، أو مؤشرات وحدات العمل مع الحجم.')
]
for heading,title,body,code,comments,plot,en,ar in GEOMS:
    add(4,heading,title,body,code,comments,plot=None)
    add(4,heading,title+': example',en,arabic=ar,plot=plot,kind='plot',hint='Same example data and geometry as the Quarto lesson.')
    if plot=='boxplot':
        add(4,heading,'Boxplot variants in the lesson','Compare cylinder groups directly or use one facet per group.\ntheme_bw() applies a white background with reference grid lines.',code='ggplot(mtcars, aes(x = factor(cyl), y = mpg)) +\n  geom_boxplot() + theme_bw()\nggplot(mtcars, aes(y = mpg)) +\n  geom_boxplot() + facet_wrap(~ cyl) + theme_bw()',comments=['ggplot()/aes()/factor() define groupings; geom_boxplot() summarizes distributions.','facet_wrap() splits groups into panels; theme_bw() changes nondata appearance.'],plot='box-variants')
    if plot=='text':
        add(4,heading,'Label backgrounds','The label geometry adds a background for readability.\nMany labels can still overlap.',plot='label',kind='plot')
    if plot=='column':
        add(4,heading,'Averages require a summary first','The original geom_col() example stacks row values.\nTo display means, calculate one mean per class before plotting.\nThis distinction matters when interpreting a column chart.',refs=['https://ggplot2.tidyverse.org/reference/geom_bar.html'],hint='The example is retained; the original description of its heights as averages is corrected.')
add(4,'15. **`geom_point()`** - Bubble plot','From code to a readable graphic','Choose a geometry that matches the question.\nExplain mappings and units. Check transformations and defaults.\nUse labels and a theme to make the evidence readable.',hint='Continue with the ggplot2 exercises in Quarto.')

expanded=[]
for s in SLIDES:
    if s['plot'] and s['code']:
        result=dict(s, title=s['title']+': result', code='',kind='plot',body=s['body'],hint='Read the plotted result alongside the preceding code.')
        expanded.append(dict(s,plot=None))
        expanded.append(result)
    else:
        expanded.append(s)
SLIDES=expanded
for i,s in enumerate(SLIDES,1): s['number']=i
starts={s['lesson']:s['number'] for s in SLIDES if s['kind']=='divider' and s['title'].startswith('Lesson ')}
SLIDES[0]['body']='\n'.join(f"Lesson {i}: {label}  (slide {starts[i]})" for i,label in enumerate(['R and RStudio','Basic concepts in R','Data manipulation with dplyr','Visualization with ggplot2'],1))
(OUT/'slides.json').write_text(json.dumps(SLIDES,ensure_ascii=False,indent=2))
# Coverage tracks substantive lesson headings, with generic Syntax/Example headings
# covered through their containing conceptual section, rather than counted as new topics.
rows=[]
for lesson,source in SOURCES.items():
    inside=False
    for line_no,line in enumerate(source.splitlines(),1):
        if line.lstrip().startswith('```'): inside=not inside
        if inside or not re.match(r'^#{1,6} ',line): continue
        heading=re.sub(r'^#+ ','',line)
        mapped=[s['number'] for s in SLIDES if s['lesson']==lesson and s['start']<=line_no<=s['end']]
        rows.append({'lesson':lesson,'line':line_no,'heading':heading,'slides':mapped})
missing=[r for r in rows if not r['slides']]
(OUT/'coverage.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
assert not missing, missing
manifest={'source_sha256':{str(FILES[k].relative_to(ROOT)):hashlib.sha256(v.encode()).hexdigest() for k,v in SOURCES.items()},'slide_count':len(SLIDES),'lesson_counts':{i:sum(s['lesson']==i for s in SLIDES) for i in FILES},'headings_checked':len(rows),'unmapped_headings':missing}
(OUT/'content-manifest.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps({k:v for k,v in manifest.items() if k!='source_sha256'}))
